def parse_num(s):
    s = s.replace('零', '0')
    s = s.replace('一', '1').replace('二', '2').replace('三', '3').replace('四', '4').replace('五', '5')
    s = s.replace('六', '6').replace('七', '7').replace('八', '8').replace('九', '9')
    s = s.replace('十', '0').replace('百', '0')
    if not s.isdigit():
        # Handle 一百 (100), 一千 (1000), etc.
        s2 = s.replace('零', '').replace('一', '1').replace('二', '2').replace('三', '3').replace('四', '4').replace('五', '5')
        s2 = s2.replace('六', '6').replace('七', '7').replace('八', '8').replace('九', '9')
        s2 = s2.replace('百', '0').replace('十', '0')
        try:
            return int(s2)
        except:
            return -1
    return int(s)

